const SHEETS = [
  '2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration',
  'Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab',
  'Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'
];
return SHEETS.map(s => ({ json: { sheet_name: s } }));

// Report-only -- builds one HEAD-check item per populated IMAGE URL slot on
// every row that has a Product No. This never writes anything back to the
// sheet's IMAGE URL columns and never re-queues a row for reprocessing --
// see README. Only rows with at least one populated image slot are relevant.
const sheetName = $('🔄 Loop Through Sheets').item.json.sheet_name;
const rows = items.map(i => i.json);
const hasValue = v => v !== undefined && v !== null && String(v).trim() !== '';

const checks = [];
for (const r of rows) {
  if (!hasValue(r['Product No.'])) continue;
  for (let n = 1; n <= 11; n++) {
    const url = String(r[`IMAGE URL${n}`] ?? '').trim();
    if (!/^https?:\/\//i.test(url)) continue;
    checks.push({ json: {
      url, slot: `IMAGE URL${n}`, row_number: r.row_number, sheet_name: sheetName,
      product_no: r['Product No.']
    } });
  }
}
return checks.length ? checks : [{ json: { _skipCheck: true, sheet_name: sheetName } }];

// Shopify's CDN has a known propagation delay after a file is uploaded, renamed,
// or deleted+recreated -- a single 404 during that window is not proof the file
// is actually gone. This only flags suspects; '🩺 Confirm Dead Image URLs'
// re-checks them after a wait and only reports ones STILL dead on the second check.
//
// Match each HTTP result back to its originating check via pairedItem, not
// array position -- results[i] <-> checks[i] zipping silently breaks if the
// batched HTTP node ever returns items in a different order or count than
// went in (a real risk under network-level errors even with neverError:
// true), which would misattribute a status code to the wrong URL and let a
// genuinely dead image go unreported with no visible error.
const results = $input.all();
const checks  = $('🩺 Build URL Checks').all();

const DEAD = new Set([404, 410]);
const suspects = [];
for (const r of results) {
  const idx = typeof r.pairedItem === 'number' ? r.pairedItem : r.pairedItem?.item;
  const c = idx !== undefined ? checks[idx]?.json : undefined;
  const status = r.json?.statusCode;
  if (!c || !DEAD.has(status)) continue;
  suspects.push({ ...c, status });
}
return suspects.length ? suspects.map(s => ({ json: s })) : [{ json: { _noSuspects: true } }];

// Only URLs that are STILL 404/410 after the wait are treated as genuinely
// dead -- filters out CDN propagation-delay false positives. Report-only: this
// never writes to any IMAGE URL column and never re-queues the row.
//
// Same pairedItem matching as '🩺 Find Suspect Image URLs' -- see that node's
// comment for why array-position zipping (results[i] <-> suspects[i]) is
// unsafe here.
const results  = $input.all();
const suspects = $('🩺 Find Suspect Image URLs').all();

const DEAD = new Set([404, 410]);
const dead = [];
for (const r of results) {
  const idx = typeof r.pairedItem === 'number' ? r.pairedItem : r.pairedItem?.item;
  const c = idx !== undefined ? suspects[idx]?.json : undefined;
  const status = r.json?.statusCode;
  if (!c || !DEAD.has(status)) continue;
  dead.push({
    checked_at: $now,
    sheet_name: c.sheet_name,
    row_number: c.row_number,
    'Product No.': c.product_no,
    slot: c.slot,
    dead_url: c.url,
    status_code: status
  });
}
return dead.length ? dead.map(d => ({ json: d })) : [{ json: { _noneDead: true } }];
